head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf10007";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — action_path

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf10007.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSslReturn
 * @description fn Ssl Return 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSslReturn = async function () {
    const fm = (document.frm || { elements: [] });
    const path = (String(((dma_pageContext.get("action_path") ?? "")) === null ? '' : ((dma_pageContext.get("action_path") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("action_path") ?? "")) === null ? '' : ((dma_pageContext.get("action_path") ?? ""))));
    const url = path.split("?");
    const paramAll = url[1].split("&");
    const acptNo = paramAll[0].split("=")[1];
    const gaskScrenID = paramAll[1].split("=")[1];
    const gaccssAuthTpCd = paramAll[2].split("=")[1];
    $c.util.getComponent("ipt_AcptNo").setValue(acptNo);
    $c.util.getComponent("ipt_gAskScrenID").setValue(gaskScrenID);
    $c.util.getComponent("ipt_gAccssAuthTpCd").setValue(gaccssAuthTpCd);
    fm.action = url[0];
    await moveUrl(url[0], {});
};
